export const SHEET  = { height: 806, topRadius: 38 };
export const COUPON = {
  w: 368, h: 125, radius: 24,
  seam: 243,          // perforation x — everything right of it is the pull tab (125pt)
  holeR: 3, notchR: 7,
  holes: Array.from({ length: 7 }, (_, i) => 18 + i * (89 / 6)),  // y of each punched hole
};
export const GESTURE = { tearAt: 62, stretch: 96, resistance: 90, confetti: 14 };
// Type scale (Urbane Rounded): headline 26/34 DemiBold, mid 17/24 Medium, tail 16/24 Light

import { Canvas, RoundedRect, Group, Path, Skia, Shadow } from '@shopify/react-native-skia';

// Perforation: rounded card MINUS 7 holes + 2 edge half-moon notches (even-odd)
export function couponPath({ w, h, radius, seam, holes, holeR, notchR }) {
  const p = Skia.Path.Make();
  p.addRRect(Skia.RRectXY(Skia.XYWHRect(0, 0, w, h), radius, radius));
  p.addCircle(seam, 0, notchR);   // top grip notch
  p.addCircle(seam, h, notchR);   // bottom grip notch
  holes.forEach(y => p.addCircle(seam, y, holeR));
  p.setFillType(1 /* FillType.EvenOdd */);
  return p;
}

// Inside the sheet <Canvas>:
// 1. (VIP/Red) ambient shadow UNDER the coupon — separate transparent rect
// 2. clip to couponPath, then:
<Group clip={couponPath(COUPON)}>
  {tier.tint && <RoundedRect x={0} y={0} width={COUPON.w} height={COUPON.h}
                             r={COUPON.radius} color={tier.tint} />}
  <RoundedRect x={0} y={0} width={COUPON.w} height={COUPON.h} r={COUPON.radius}
               color={`rgba(173,173,173,${tier.lighter})`} blendMode="plus" />
</Group>
// The pull tab is the same fills clipped right of the seam, transformed by the gesture.

const N = COUPON.holes.length;                       // 7
const travel = (dx: number) =>
  GESTURE.stretch * Math.tanh(dx / GESTURE.resistance);       // elastic resistance
const popAt = (i: number) =>
  GESTURE.tearAt * (0.30 + 0.70 * (i / (N - 1)));             // staggered thresholds

const pan = Gesture.Pan()
  .onUpdate(e => {
    const d = travel(Math.max(0, e.translationX));
    drag.value = d;
    for (let i = popped.value; i < N; i++) {
      if (d < popAt(i)) break;
      popped.value = i + 1;                 // hole i splits into half-moons
      runOnJS(popFx)(i);                    // ring burst + ejected disc + 2px card recoil
    }
    if (popped.value === N) runOnJS(tear)(); // fly-off + WHITE confetti + heal
  })
  .onEnd(() => {
    if (!torn.value) {                      // partial pull -> spring back, RESET holes
      popped.value = 0;
      drag.value = withSpring(0, { damping: 12, stiffness: 180 }); // overshoot wobble
    }
  });

// Tab transform while holes remain (hinge = seam x, y of topmost intact hole):
const tabStyle = useAnimatedStyle(() => ({
  transformOrigin: `${COUPON.seam}px ${hingeY(popped.value)}px`,
  transform: [
    { translateX: drag.value * 0.10 },
    { rotate: `${drag.value * 0.26}deg` },
  ],
}));
// Heal after tear: animate the card's clip inset back to full width over 550ms.
// Redeemed face: 'Redeemed' + dashed promo chip + white Checkout pill
// (white bg, #ED1C24 text, radius 60, height 42) — no check mark.

import * as Haptics from 'expo-haptics';
const popFx  = () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);  // each hole
const tearFx = () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
